class LmdbMaintenanceCleanupFailureIsolationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void unusedIdCleanupFailureCannotRollbackAnAdmittedStandaloneWriter(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true);
		FailureInjectingStore store = new FailureInjectingStore(directory.toFile(), config);
		ForeignWriterAfterCommitFailure injected = new ForeignWriterAfterCommitFailure(
				VF.createIRI("urn:cleanup-failure:foreign-unused-writer"));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			Value orphan = VF.createIRI("urn:cleanup-failure:unused-orphan");
			long retiredId = seedDurableRetirement(values, orphan);
			assertTrue(values.hasRetiredIds(),
					"setup must persist a durable retirement row before recovery: " + values.getLmdbStats());
			store.getBackingStore().recoverRetiredValueIds();
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(orphan),
					"setup recovery must remove the unreferenced orphan mapping");
			long unusedBefore = entries(values, "unused_ids");
			assertTrue(unusedBefore > 0L, "setup must create a real eligible persisted unused-ID cohort");
			store.failAfterUnusedReclamationCommit(injected);
			long generationBefore = values.nativeCommitGeneration();

			IOException failure = assertThrows(IOException.class,
					() -> values.reclaimPersistedUnusedIdsBatch(4096));

			assertSame(injected.failure(), failure, "the original post-commit IOException must be preserved");
			assertTrue(injected.foreignMappingReady(), "the foreign native mapping must exist before cleanup starts");
			assertNotEquals(LmdbValue.UNKNOWN_ID, injected.assignedId());
			assertSame(injected.foreignTransaction(), values.currentWriterTransaction(),
					"maintenance cleanup must leave the admitted writer publication intact before it resumes native calls");
			assertEquals(injected.maintenanceGeneration(), values.nativeCommitGeneration(),
					"the cleanup failure occurs after the maintenance commit, with no later native publication");
			assertTrue(injected.maintenanceGeneration() > generationBefore,
					"the unused-ID maintenance transaction must really have committed before the injected failure");
			assertTrue(injected.maintenanceEntries("unused_ids") < unusedBefore,
					"the committed maintenance pass must reduce the unused cohort before another writer can reuse IDs");
			assertTrue(injected.maintenanceEntries("free_ids") > 0L,
					"the committed maintenance pass must publish reclaimed IDs before foreign writer admission");

			long foreignId = injected.resumeAndAwait();
			assertEquals(injected.assignedId(), foreignId,
					"the first resumed lookup must still see the foreign writer's uncommitted mapping");
			assertEquals(foreignId, values.getId(injected.value()));
			assertEquals(injected.value(), values.getValue(foreignId));
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(orphan),
					"the committed cleanup must remove the reclaimed orphan mapping");
			assertTrue(entries(values, "unused_ids") < unusedBefore,
					"the maintenance commit must persist its unused-ID cleanup despite the thrown follow-up error");
			assertTrue(values.hasTrustedReferenceCounts());
			assertNotEquals(LmdbValue.UNKNOWN_ID, retiredId);
		} finally {
			injected.releaseForeign();
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void retirementRecoveryFailureCannotRollbackAnAdmittedStandaloneWriter(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true);
		FailureInjectingStore store = new FailureInjectingStore(directory.toFile(), config);
		ForeignWriterAfterCommitFailure injected = new ForeignWriterAfterCommitFailure(
				VF.createIRI("urn:cleanup-failure:foreign-retirement-writer"));
		store.init();
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			Value orphan = VF.createIRI("urn:cleanup-failure:retirement-orphan");
			long retiredId = seedDurableRetirement(values, orphan);
			assertTrue(values.hasRetiredIds(), "setup must persist a real durable retirement cohort");
			store.failAfterRetirementRecoveryCommit(injected);
			long generationBefore = values.nativeCommitGeneration();

			IOException failure = assertThrows(IOException.class,
					() -> store.getBackingStore().recoverRetiredValueIds());

			assertSame(injected.failure(), failure, "the original post-commit IOException must be preserved");
			assertTrue(injected.foreignMappingReady(), "the foreign native mapping must exist before cleanup starts");
			assertNotEquals(LmdbValue.UNKNOWN_ID, injected.assignedId());
			assertSame(injected.foreignTransaction(), values.currentWriterTransaction(),
					"retirement cleanup must leave the admitted writer publication intact before it resumes native calls");
			assertEquals(injected.maintenanceGeneration(), values.nativeCommitGeneration(),
					"the cleanup failure occurs after the retirement commit, with no later native publication");
			assertTrue(injected.maintenanceGeneration() > generationBefore,
					"retirement recovery must commit its real durable cohort before the injected failure");
			assertTrue(injected.maintenanceEntries("unused_ids") > 0L,
					"the committed batch must durably retire the orphan before it tries its dependent namespace frontier");

			long foreignId = injected.resumeAndAwait();
			assertEquals(injected.assignedId(), foreignId,
					"the first resumed lookup must still see the foreign writer's uncommitted mapping");
			assertEquals(foreignId, values.getId(injected.value()));
			assertEquals(injected.value(), values.getValue(foreignId));
			assertTrue(values.hasRetiredIds(),
					"one bounded batch may retain the orphan's dependent namespace frontier for later recovery");
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(orphan),
					"retirement recovery must remove the unreferenced dictionary mapping");
			assertTrue(values.hasTrustedReferenceCounts());
			assertNotEquals(LmdbValue.UNKNOWN_ID, retiredId);
		} finally {
			injected.releaseForeign();
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void readOnlySailRollbackDispatchesBothNullTicketRollbacksWithoutCancellingForeignWriter(
			@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setForceSync(true);
		NullTicketRollbackStore store = new NullTicketRollbackStore(directory.toFile(), config);
		store.init();
		HeldStandaloneValueWriter foreignWriter = null;
		try {
			ValueStore values = LmdbGcTestMaintenance.awaitTrustedReclamationSetup(store);
			Value value = VF.createIRI("urn:cleanup-failure:null-ticket-foreign-writer");
			foreignWriter = new HeldStandaloneValueWriter(values, value);
			foreignWriter.start();
			foreignWriter.awaitMapping();
			assertSame(foreignWriter.transaction(), values.currentWriterTransaction(),
					"the real standalone writer must own the ValueStore publication before Sail rollback");
			long generationBeforeRollback = values.nativeCommitGeneration();
			store.armNullTicketRollback();

			try (SailConnection readOnly = store.getConnection()) {
				readOnly.begin(IsolationLevels.SNAPSHOT);
				assertTrue(readOnly.isActive(), "the Sail connection must hold a read-only logical transaction");
				SailException failure = assertThrows(SailException.class, readOnly::rollback,
						"both virtual store rollback entry points must report their injected cleanup failures");
				store.disarmNullTicketRollback();
				assertSame(store.valueRollbackFailure(), failure.getCause(),
						"the ValueStore rollback failure must remain the primary cause");
				assertEquals(1, store.valueRollbackFailure().getSuppressed().length,
						"the TripleStore rollback failure must be retained as suppressed cleanup");
				assertSame(store.tripleRollbackFailure(), store.valueRollbackFailure().getSuppressed()[0]);
				assertEquals(1, store.valueRollbackCalls(), "the public ValueStore rollback override must be invoked");
				assertEquals(1, store.tripleRollbackCalls(),
						"the public TripleStore rollback override must be invoked");
				assertNotNull(store.valueRollbackTicket(),
						"ValueStore rollback must run with an explicit cleanup ticket");
				assertNotNull(store.tripleRollbackTicket(),
						"TripleStore rollback must run with an explicit cleanup ticket");
				assertNotEquals(foreignWriter.transaction(), store.valueRollbackTicket(),
						"the null-native rollback must use a ticket that is not the foreign writer's ticket");
				assertNotEquals(foreignWriter.transaction(), store.tripleRollbackTicket(),
						"the TripleStore rollback must not borrow the foreign writer's ticket");
				assertSame(foreignWriter.transaction(), values.currentWriterTransaction(),
						"read-only Sail rollback must leave the foreign logical writer publication intact before resume");
				assertEquals(generationBeforeRollback, values.nativeCommitGeneration(),
						"rollback must not commit or abort the foreign native writer before it resumes");
				assertFalse(foreignWriter.committed(), "the foreign writer must still be held before resume");
			} finally {
				store.disarmNullTicketRollback();
			}

			long committedId = foreignWriter.resumeAndAwait();
			assertEquals(foreignWriter.assignedId(), committedId);
			assertEquals(committedId, values.getId(value), "the foreign mapping must survive and become committed");
			assertEquals(value, values.getValue(committedId),
					"the committed mapping must resolve to its original value");
			assertEquals(generationBeforeRollback + 1L, values.nativeCommitGeneration(),
					"only the resumed foreign writer may advance the native commit generation");
			assertTrue(values.hasTrustedReferenceCounts(), "the trusted count proof must survive the rollback attempt");
		} finally {
			store.disarmNullTicketRollback();
			if (foreignWriter != null) {
				foreignWriter.releaseAndJoin();
			}
			store.shutDown();
		}
	}

	private static long seedDurableRetirement(ValueStore values, Value orphan) throws IOException {
		values.startTransaction(true);
		long id = values.storeValue(orphan);
		values.commit();
		values.startTransaction(true);
		values.recordRetiredIds(Set.of(id), 0L);
		values.commit();
		return id;
	}

	private static long entries(ValueStore values, String database) throws IOException {
		return values.getLmdbStats().get(database).entries();
	}

	private static final class FailureInjectingStore extends LmdbStore {

		private final AtomicReference<TargetedMaintenance> armedTarget = new AtomicReference<>();
		private final AtomicReference<ForeignWriterAfterCommitFailure> armedFailure = new AtomicReference<>();
		private final AtomicLong targetCommitReady = new AtomicLong();

		private FailureInjectingStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches,
					(valueDirectory, valueProperties, valueConfig) -> new ValueStore(valueDirectory, valueProperties,
							valueConfig) {
						@Override
						void observeBoundedUnusedReclamationForTest(String phase, long requiredBytes,
								long occupiedBytes,
								long mapBytes, int visited) {
							if (phase.equals("visited")) {
								maintenanceActionReached(TargetedMaintenance.PERSISTED_UNUSED_RECLAMATION);
							}
						}

						@Override
						void removeRetiredIds(RetiredValueIdStore.DrainBatch batch) throws IOException {
							super.removeRetiredIds(batch);
							if (!batch.isEmpty()) {
								maintenanceActionReached(TargetedMaintenance.RETIRED_ID_RECOVERY);
							}
						}

						@Override
						public void commit() throws IOException {
							super.commit();
							ForeignWriterAfterCommitFailure failure = takeTargetedFailure();
							if (failure != null) {
								failure.afterMaintenanceCommit(this);
							}
						}
					}, TripleStore::new);
		}

		private void failAfterUnusedReclamationCommit(ForeignWriterAfterCommitFailure failure) {
			arm(TargetedMaintenance.PERSISTED_UNUSED_RECLAMATION, failure);
		}

		private void failAfterRetirementRecoveryCommit(ForeignWriterAfterCommitFailure failure) {
			arm(TargetedMaintenance.RETIRED_ID_RECOVERY, failure);
		}

		private void arm(TargetedMaintenance target, ForeignWriterAfterCommitFailure failure) {
			assertTrue(armedFailure.compareAndSet(null, failure), "only one maintenance failure may be armed");
			assertTrue(armedTarget.compareAndSet(null, target), "only one maintenance owner may be targeted");
		}

		private void maintenanceActionReached(TargetedMaintenance action) {
			if (armedTarget.compareAndSet(action, null)) {
				targetCommitReady.incrementAndGet();
			}
		}

		private ForeignWriterAfterCommitFailure takeTargetedFailure() {
			if (targetCommitReady.compareAndSet(1L, 0L)) {
				return armedFailure.getAndSet(null);
			}
			return null;
		}
	}

	private static final class NullTicketRollbackStore extends LmdbStore {

		private final IOException valueRollbackFailure = new IOException(
				"injected ValueStore null-ticket rollback failure");
		private final IOException tripleRollbackFailure = new IOException(
				"injected TripleStore null-ticket rollback failure");
		private final AtomicBoolean observeNullTicketRollback = new AtomicBoolean();
		private final AtomicInteger valueRollbackCalls = new AtomicInteger();
		private final AtomicInteger tripleRollbackCalls = new AtomicInteger();
		private final AtomicReference<WriterTransaction> valueRollbackTicket = new AtomicReference<>();
		private final AtomicReference<WriterTransaction> tripleRollbackTicket = new AtomicReference<>();

		private NullTicketRollbackStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches,
					(valueDirectory, valueProperties, valueConfig) -> new ValueStore(valueDirectory, valueProperties,
							valueConfig) {
						@Override
						public void rollback() throws IOException {
							if (!observeNullTicketRollback.get()) {
								super.rollback();
								return;
							}
							valueRollbackCalls.incrementAndGet();
							valueRollbackTicket.set(WriterTransaction.current());
							super.rollback();
							throw valueRollbackFailure;
						}
					},
					(tripleDirectory, tripleProperties, tripleConfig, values) -> new TripleStore(tripleDirectory,
							tripleProperties, tripleConfig, values) {
						@Override
						public void rollback() throws IOException {
							if (!observeNullTicketRollback.get()) {
								super.rollback();
								return;
							}
							tripleRollbackCalls.incrementAndGet();
							tripleRollbackTicket.set(WriterTransaction.current());
							super.rollback();
							throw tripleRollbackFailure;
						}
					});
		}

		private void armNullTicketRollback() {
			assertTrue(observeNullTicketRollback.compareAndSet(false, true));
		}

		private void disarmNullTicketRollback() {
			observeNullTicketRollback.set(false);
		}

		private IOException valueRollbackFailure() {
			return valueRollbackFailure;
		}

		private IOException tripleRollbackFailure() {
			return tripleRollbackFailure;
		}

		private int valueRollbackCalls() {
			return valueRollbackCalls.get();
		}

		private int tripleRollbackCalls() {
			return tripleRollbackCalls.get();
		}

		private WriterTransaction valueRollbackTicket() {
			return valueRollbackTicket.get();
		}

		private WriterTransaction tripleRollbackTicket() {
			return tripleRollbackTicket.get();
		}
	}

	private enum TargetedMaintenance {
		PERSISTED_UNUSED_RECLAMATION,
		RETIRED_ID_RECOVERY
	}

	private static final class ForeignWriterAfterCommitFailure {

		private final Value value;
		private final IOException failure = new IOException("injected failure after maintenance native commit");
		private final CountDownLatch mappingReady = new CountDownLatch(1);
		private final CountDownLatch resume = new CountDownLatch(1);
		private final CompletableFuture<Long> committedId = new CompletableFuture<>();
		private final AtomicReference<WriterTransaction> foreignTransaction = new AtomicReference<>();
		private final AtomicReference<Thread> foreignThread = new AtomicReference<>();
		private final AtomicLong assignedId = new AtomicLong(LmdbValue.UNKNOWN_ID);
		private final AtomicLong maintenanceGeneration = new AtomicLong();
		private final AtomicReference<Throwable> workerFailure = new AtomicReference<>();
		private Map<String, LmdbStore.LmdbDatabaseStats> maintenanceStats;

		private ForeignWriterAfterCommitFailure(Value value) {
			this.value = value;
		}

		private void afterMaintenanceCommit(ValueStore values) throws IOException {
			maintenanceGeneration.set(values.nativeCommitGeneration());
			maintenanceStats = values.getLmdbStats();
			WriterTransaction transaction = new WriterTransaction();
			Thread worker = Thread.ofPlatform().name("foreign-standalone-value-writer").unstarted(() -> {
				try {
					values.startTransaction(true, transaction);
					foreignTransaction.set(values.currentWriterTransaction());
					assignedId.set(values.storeValue(value));
					mappingReady.countDown();
					if (!resume.await(10L, TimeUnit.SECONDS)) {
						throw new AssertionError("foreign writer was not released after cleanup finished");
					}
					assertEquals(assignedId.get(), values.getId(value),
							"foreign writer must retain its mapping through the cleanup failure");
					values.commit();
					committedId.complete(assignedId.get());
				} catch (Throwable problem) {
					workerFailure.set(problem);
					committedId.completeExceptionally(problem);
				} finally {
					try {
						values.rollback(transaction);
					} catch (Throwable cleanup) {
						Throwable problem = workerFailure.get();
						if (problem != null && problem != cleanup) {
							problem.addSuppressed(cleanup);
						}
					}
				}
			});
			foreignThread.set(worker);
			worker.start();
			try {
				if (!mappingReady.await(10L, TimeUnit.SECONDS)) {
					Throwable problem = workerFailure.get();
					throw new IOException("foreign standalone writer did not admit and publish its uncommitted mapping",
							problem);
				}
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new IOException("interrupted while waiting for foreign standalone writer admission", interrupted);
			}
			throw failure;
		}

		private boolean foreignMappingReady() {
			return mappingReady.getCount() == 0L;
		}

		private long assignedId() {
			return assignedId.get();
		}

		private Value value() {
			return value;
		}

		private IOException failure() {
			return failure;
		}

		private WriterTransaction foreignTransaction() {
			return foreignTransaction.get();
		}

		private long maintenanceGeneration() {
			return maintenanceGeneration.get();
		}

		private long maintenanceEntries(String database) {
			return maintenanceStats.get(database).entries();
		}

		private long resumeAndAwait() throws Exception {
			resume.countDown();
			try {
				return committedId.get(10L, TimeUnit.SECONDS);
			} finally {
				Thread worker = foreignThread.get();
				if (worker != null) {
					worker.join(10_000L);
					assertFalse(worker.isAlive(), "foreign writer must finish after it is released");
				}
			}
		}

		private void releaseForeign() {
			resume.countDown();
		}
	}

	private static final class HeldStandaloneValueWriter {

		private final ValueStore values;
		private final Value value;
		private final WriterTransaction transaction = new WriterTransaction();
		private final CountDownLatch mappingReady = new CountDownLatch(1);
		private final CountDownLatch resume = new CountDownLatch(1);
		private final CompletableFuture<Long> committedId = new CompletableFuture<>();
		private final AtomicReference<Throwable> workerFailure = new AtomicReference<>();
		private final AtomicLong assignedId = new AtomicLong(LmdbValue.UNKNOWN_ID);
		private final Thread worker;

		private HeldStandaloneValueWriter(ValueStore values, Value value) {
			this.values = values;
			this.value = value;
			worker = Thread.ofPlatform().name("held-null-ticket-value-writer").unstarted(() -> {
				try {
					values.startTransaction(true, transaction);
					assignedId.set(values.storeValue(value));
					mappingReady.countDown();
					if (!resume.await(10L, TimeUnit.SECONDS)) {
						throw new AssertionError("foreign standalone writer was not released after logical rollback");
					}
					assertEquals(assignedId.get(), values.getId(value),
							"the writer must still see its uncommitted mapping after the other rollback");
					values.commit();
					committedId.complete(assignedId.get());
				} catch (Throwable failure) {
					workerFailure.set(failure);
					committedId.completeExceptionally(failure);
				} finally {
					mappingReady.countDown();
					try {
						values.rollback(transaction);
					} catch (Throwable cleanupFailure) {
						Throwable failure = workerFailure.get();
						if (failure == null) {
							workerFailure.set(cleanupFailure);
						} else if (cleanupFailure != failure) {
							failure.addSuppressed(cleanupFailure);
						}
					}
				}
			});
		}

		private void start() {
			worker.start();
		}

		private void awaitMapping() throws Exception {
			assertTrue(mappingReady.await(10L, TimeUnit.SECONDS),
					"foreign writer must publish its uncommitted mapping");
			rethrowWorkerFailure();
			assertNotEquals(LmdbValue.UNKNOWN_ID, assignedId.get());
		}

		private WriterTransaction transaction() {
			return transaction;
		}

		private long assignedId() {
			return assignedId.get();
		}

		private boolean committed() {
			return committedId.isDone();
		}

		private long resumeAndAwait() throws Exception {
			resume.countDown();
			try {
				long id = committedId.get(10L, TimeUnit.SECONDS);
				worker.join(TimeUnit.SECONDS.toMillis(10L));
				assertFalse(worker.isAlive(), "foreign writer must terminate after commit");
				rethrowWorkerFailure();
				return id;
			} catch (ExecutionException e) {
				throw new AssertionError("foreign standalone writer failed", e.getCause());
			}
		}

		private void releaseAndJoin() throws InterruptedException {
			resume.countDown();
			worker.join(TimeUnit.SECONDS.toMillis(10L));
			if (worker.isAlive()) {
				worker.interrupt();
				worker.join(TimeUnit.SECONDS.toMillis(2L));
			}
		}

		private void rethrowWorkerFailure() throws Exception {
			Throwable failure = workerFailure.get();
			if (failure instanceof Exception exception) {
				throw exception;
			}
			if (failure instanceof Error error) {
				throw error;
			}
		}
	}
}
